# Server-based token estimation
def estimate_tokens(text):
    try:
        r = requests.post(TOKENIZER_URL, json={"prompt": text})
        return len(r.json().get("tokens", []))
    except:
        return len(text) // 4
# Tree-sitter parsers
def extract_function_bodies(node, valid_nodes):
    stack, collected, visited = [node], [], set()
    while stack:
        current = stack.pop()
        if current.id in visited:
            continue
        visited.add(current.id)
        parent_type = current.parent.type if current.parent else ""
        if current.type in valid_nodes and parent_type not in valid_nodes:
            collected.append(current)
        else:
            stack.extend(current.children)
    return collected
def extract_doc_comment(code, start_byte):
    lines = code[:start_byte].splitlines()
    comment_lines = []
    for line in reversed(lines[-10:]):
        if re.match(r"\s*(#|//|/\*|\*)", line):
            comment_lines.insert(0, line.strip())
        elif comment_lines:
            break
    return '\n'.join(comment_lines) + '\n' if comment_lines else ''
def extract_smart_overlap(chunk_lines, overlap_tokens):
    overlap, token_count = [], 0
    for line in reversed(chunk_lines):
        overlap.insert(0, line)
        token_count += estimate_tokens(line + '\n')
        if token_count >= overlap_tokens or re.match(r"\s*(def |class |//|#|function |[\w\s]+\{)", line):
            break
    return overlap
def chunk_code_by_syntax(code, max_tokens, rel_path):
    suffix = Path(rel_path).suffix
    parser, valid_nodes = None, []
    if suffix in {".cpp", ".c", ".cc", ".cxx", ".h", ".hpp"}:
        parser, valid_nodes = parser_cpp, ("function_definition", "class_specifier", "struct_specifier")
    elif suffix == ".py":
        parser, valid_nodes = parser_py, ("function_definition", "class_definition")
    elif suffix == ".java":
        parser, valid_nodes = parser_java, ("class_declaration", "method_declaration", "constructor_declaration", "interface_declaration")
    elif suffix in {".js", ".mjs"}:
        parser, valid_nodes = parser_js, ("function_declaration", "function", "method_definition", "arrow_function", "class_declaration")
    else:
        return []

    tree = parser.parse(bytes(code, "utf8"))
    nodes = sorted(extract_function_bodies(tree.root_node, valid_nodes), key=lambda n: n.start_byte)

    chunks, current_chunk, current_tokens, chunk_id = [], [], 0, 0
    last_overlap = []

    for node in nodes:
        snippet = code[node.start_byte:node.end_byte].strip()
        if not snippet:
            continue
        full_snippet = extract_doc_comment(code, node.start_byte) + snippet
        if not full_snippet.strip():
            continue
        token_count = estimate_tokens(full_snippet)

        if current_tokens + token_count > max_tokens and current_chunk:
            header = f"// FILE: {rel_path}\n// CHUNK {chunk_id} | estimated_tokens: {current_tokens}\n\n"
            chunks.append(header + '\n'.join(current_chunk))
            last_overlap = extract_smart_overlap(current_chunk, OVERLAP_TOKENS)
            current_chunk = last_overlap[:]
            current_tokens = sum(estimate_tokens(line + '\n') for line in current_chunk)
            chunk_id += 1

        current_chunk.extend(full_snippet.splitlines())
        current_tokens += token_count

    if current_chunk:
        header = f"// FILE: {rel_path}\n// CHUNK {chunk_id} | estimated_tokens: {current_tokens}\n\n"
        chunks.append(header + '\n'.join(current_chunk))
    return chunks
def write_chunks(chunks, rel_path):
    if not chunks:
        return False
    out_file = CHUNK_OUT_DIR / rel_path.parent / f"{rel_path.stem}.jsonl"
    out_file.parent.mkdir(parents=True, exist_ok=True)
    with open(out_file, 'wb') as f:
        for i, chunk in enumerate(chunks):
            if not chunk.strip():
                continue
            data = {
                "file": str(rel_path),
                "chunk_id": i,
                "code": chunk,
                "tokens": estimate_tokens(chunk)
            }
            f.write(orjson.dumps(data) + b"\n")
    return True
def hash_file(path):
    with open(path, 'rb') as f:
        return hashlib.md5(f.read()).hexdigest()
def process_file(path):
    rel_path = path.relative_to(SOURCE_DIR)
    cache_file = CACHE_DIR / f"{rel_path}.hash"
    chunk_path = CHUNK_OUT_DIR / rel_path.parent / f"{rel_path.stem}.jsonl"

    try:
        if path.suffix not in ALLOWED_EXTS:
            return False
        if chunk_path.exists():
            chunk_path.unlink() # already processed

        code = path.read_text(encoding='utf-8')
        chunks = chunk_code_by_syntax(code, MAX_TOKENS, rel_path)
        if not write_chunks(chunks, rel_path):
            with open(UNCHUNKED_LOG, 'a') as log:
                log.write(f"{rel_path} [empty or failed]\n")
            return False
        cache_file.parent.mkdir(parents=True, exist_ok=True)
        cache_file.write_text(hash_file(path))
        return True
    except Exception as e:
        with open(UNCHUNKED_LOG, 'a') as log:
            log.write(f"{rel_path} [error: {e}]\n")
        return False
def main():
    if UNCHUNKED_LOG.exists():
        UNCHUNKED_LOG.unlink()
    all_files = [f for f in SOURCE_DIR.rglob("*") if f.is_file() and f.suffix in ALLOWED_EXTS]
    with multiprocessing.Pool(processes=NUM_PROCESSES) as pool:
        results = list(tqdm(pool.imap_unordered(process_file, all_files), total=len(all_files), desc="Chunking"))
    print(f"\n✅ Done. Chunked {sum(results)} files. Skipped {len(results) - sum(results)}.")
